from pathlib import Path
from html import escape
ROOT=Path(__file__).parent/'dist'
def t(es,en,tag='span',cls=''):
 return f'<{tag}'+(f' class="{cls}"' if cls else '')+f' data-es="{escape(es,quote=True)}" data-en="{escape(en,quote=True)}">{es}</{tag}>'
def a(es,en,href,cls='',extra=''): return f'<a href="{href}" class="{cls}" {extra}>{t(es,en)}</a>'
def btn(es,en,cls='',extra=''): return f'<button class="{cls}" {extra}>{t(es,en)}</button>'
def head(page='home'):
 extra_head='<link rel="stylesheet" href="/proforma.css"><script src="/vendor/three.min.js" defer></script><script src="/viewer-controls.js" defer></script><script src="/proforma.js" defer></script>' if page in ('proforma','project') else ''
 title={'home':'Alpha Builders · Concept Studio','project':'Pixel · Alpha Builders · Concept Studio','about':'Equipo de la propuesta · Martín Vélez Falconí & Alvaro Paz','proforma':'Proforma · Tres niveles · Alpha Builders · Concept Studio'}.get(page,'Alpha Builders · Concept Studio')
 description='Martín Vélez Falconí y Alvaro Paz: el equipo detrás de la propuesta digital para Alpha Builders.' if page=='about' else 'Proforma demostrativa en tres niveles: bot de WhatsApp y gestor central, edificios en 2D, y modelos 3D con visitas virtuales.' if page=='proforma' else 'Propuesta conceptual para Alpha Builders: tres direcciones visuales y una experiencia de proyecto.'
 return f'''<!doctype html><html lang="es-EC"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{description}"><title>{title}</title><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' fill='%23212b22'/%3E%3Cpath d='M6 25L16 6l10 19h-5l-5-10-5 10Z' fill='%23d5bc7c'/%3E%3C/svg%3E"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/directions.css"><script>document.documentElement.classList.add('js')</script><script src="/app.js" defer></script><script src="/directions.js" defer></script>{extra_head}</head><body class="immersive page-{page}"><a class="skip" href="#main">{t('Saltar al contenido','Skip to content')}</a>
 <div class="studio-bar"><a class="studio-sign" href="/" aria-label="Concept Studio"><i class="studio-square"></i>CONCEPT STUDIO<small>ALPHA BUILDERS</small></a><div class="directions js-only" role="group" aria-label="Visual direction">{''.join('<button data-style="'+s+'" aria-pressed="'+str(s=='immersive').lower()+'"><b>0'+str(i+1)+'</b>'+t(es,en)+'<small>'+t(*{'essential':('Básico','Basic'),'editorial':('Medio','Mid'),'immersive':('Alto','High')}[s])+'</small></button>' for i,(s,es,en) in enumerate([('essential','Esencial','Essential'),('editorial','Editorial','Editorial'),('immersive','Inmersivo','Immersive')]))}</div><div class="studio-tools"><details class="studio-menu"><summary>{t('Propuesta','Proposal')}</summary><div class="studio-menu-panel">{btn('Comparar direcciones','Compare directions','js-only','data-open="proposal"')}{a('Alcance e inversión','Scope & investment','/proforma/','studio-quote','aria-current="page"' if page=='proforma' else '')}{a('Equipo de la propuesta','Proposal team','/nosotros/','','aria-current="page"' if page=='about' else '')}</div></details><div class="lang-switch js-only" role="group" aria-label="Language"><button data-lang="es" aria-pressed="true">ES</button><span>/</span><button data-lang="en" aria-pressed="false">EN</button></div></div></div>'''
def nav(project=False):
 logo='<span class="pixel-word">p<span>i</span>xel<i>.</i></span>' if project else '<img class="brand-logo" src="/assets/alpha-logo-white.webp" alt="Alpha Builders" width="200" height="60">'
 return f'''<header class="site-nav"><a class="brand" href="{'/pixel/' if project else '/'}">{logo}</a><nav class="site-links" aria-label="Principal">{a('El proyecto' if project else 'Proyectos','The project' if project else 'Projects','#details' if project else '#projects')}{a('Ubicación' if project else 'Nuestra visión','Location' if project else 'Our vision','#location' if project else '#vision','optional')}{a('Contacto' if project else 'Conocer Pixel','Contact' if project else 'Discover Pixel','#contact' if project else '/pixel/')}</nav><span class="nav-location">{t('UN PROYECTO DE ALPHA BUILDERS','A PROJECT BY ALPHA BUILDERS') if project else 'QUITO, ECUADOR'}</span></header>'''
def map_peek():return f'''<button class="map-peek js-only" data-open="map" aria-label="Ver ubicación de Pixel"><img src="/assets/pixel-map.webp" alt="Mapa de referencia de Pixel" width="240" height="108"><span class="map-caption"><span><b>{t('Encuentra tu lugar','Find your place')}</b><br><small>PIXEL · LA MAGDALENA</small></span><span class="map-icon"><svg viewBox="0 0 20 20"><path d="M16 8c0 5-6 9-6 9S4 13 4 8a6 6 0 1 1 12 0Z"/><circle cx="10" cy="8" r="2"/></svg></span></span></button>'''
def footer():return f'''<footer class="footer"><span>ALPHA BUILDERS · CONCEPT STUDIO © 2026</span>{a('Equipo de la propuesta','Proposal team','/nosotros/')}<span>{t('Concepto para evaluación · No es el sitio comercial','Concept for review · Not the commercial website')}</span><a href="https://alphabuildershq.com/" target="_blank" rel="noopener">{t('Sitio actual','Current website')}</a></footer>'''
def proposal():return f'''<dialog id="proposal" class="dialog"><div class="dialog-head"><b>ALPHA BUILDERS / CONCEPT STUDIO</b><button class="close" data-close aria-label="Close / Cerrar">×</button></div><div class="dialog-body">{t('Una visión compartida.<br>Tres formas de expresarla.','One shared vision.<br>Three ways to express it.','h2')}<p class="lead">{t('Una marca que inspira confianza. Cada proyecto con su propia personalidad. Información clara para quien decide rápido y una visita opcional para quien quiere descubrir más.','A brand that inspires trust. A distinct personality for every project. Clear information for quick decisions, and an optional journey for those who want to explore.')}</p><div class="proposal-grid">'''+''.join(f'''<section><small>{n} / {t(level,levelen)}</small>{t(name,nameen,'h3')}{t(desc,descen,'p')}<button class="text-link" data-choose="{s}">{t('Ver dirección','View direction')}</button></section>''' for n,level,levelen,name,nameen,desc,descen,s in [
 ('01','BÁSICO','BASIC','Esencial','Essential','Un catálogo claro para encontrar un proyecto, comparar sus datos y contactar al equipo.','A clear catalogue to find a project, compare its facts and contact the team.','essential'),
 ('02','MEDIO','MID','Editorial','Editorial','Una lectura arquitectónica del proyecto: imágenes, contexto y selección de unidades en 2D.','An architectural reading of the project: images, context and 2D home selection.','editorial'),
 ('03','ALTO','HIGH','Inmersivo','Immersive','Dirección de arte, profundidad y movimiento. Incluye la experiencia 2D, la maqueta 3D y las visitas virtuales descritas en la proforma.','Art direction, depth and motion. Includes the 2D experience, 3D model and virtual visits described in the quote.','immersive')])+f'''</div><div class="proposal-note">{t('La misma base en los tres niveles: sitio de marca, 15 sitios de proyecto y un gestor central. Medio añade selección en 2D y Alto incorpora también 3D y visitas virtuales; todos cubren el alcance obligatorio del brief.','The same foundation across all three levels: a brand site, 15 project sites and one central content system. Mid adds 2D selection and High also includes 3D and virtual visits; every tier covers the required brief scope.')}<br><br>{t('Esta muestra incluye la portada de marca, Pixel, el equipo y la proforma con demos de gestor, 2D y 3D. El inventario y las geometrías son ilustrativos; las visitas usan renders de Pixel. Los entregables de producción se rigen por la proforma y requieren planos y activos aprobados.','This preview includes the brand homepage, Pixel, the team and the quote with manager, 2D and 3D demos. Inventory and geometry are illustrative; visits use Pixel renders. Production deliverables follow the quote and require approved plans and assets.')}<br><br>{t('La opción en inglés corresponde a esta presentación. El brief establece español de Ecuador para producción. Precios, disponibilidad, estado y fechas de entrega requieren la fuente oficial aprobada.','English is available for this presentation. The brief specifies Ecuadorian Spanish for production. Prices, availability, status and delivery dates require the approved official source.')}</div><p class="source-list">{t('Imágenes y referencias:','Images and references:')} <a href="https://alphabuildershq.com/magnus/" target="_blank" rel="noopener">Alpha Builders</a> · <a href="https://pixel.com.ec/" target="_blank" rel="noopener">Pixel</a>. {t('Material de referencia para revisión privada; derechos de sus titulares.','Reference material for private review; rights remain with their owners.')}</p></div></dialog>'''
def map_dialog():return f'''<dialog id="map" class="dialog map-dialog"><div class="dialog-head"><b>{t('EL LUGAR IMPORTA','LOCATION MATTERS')}</b><button class="close" data-close aria-label="Close / Cerrar">×</button></div><img class="map-large" src="/assets/pixel-map.webp" alt="Mapa de referencia: Pixel, Av. 5 de Junio y Rodrigo de Chávez"><div class="map-details"><span class="eyebrow">QUITO / LA MAGDALENA</span><h2>Pixel</h2><p>Av. 5 de Junio y Rodrigo de Chávez, esquina.</p>{a('Abrir en Google Maps','Open in Google Maps','https://maps.app.goo.gl/JJozcsbpJE2bbfue7','button','target="_blank" rel="noopener"')}<p class="map-disclosure">{t('Mapa de referencia publicado por Pixel. La dirección también está disponible en texto; no se necesita activar tu ubicación.','Reference map published by Pixel. The address is also available as text; location access is not needed.')}</p></div></dialog>'''
def home():
 from directions import home as render_home
 render_home()

def tour_dialog():
 return f'''<dialog id="tour" class="dialog tour-dialog"><div class="dialog-head"><b>PIXEL / {t('UNA VISITA A TU RITMO','A VISIT AT YOUR PACE')}</b><button class="close" data-close aria-label="Close / Cerrar">×</button></div><div class="tour-layout"><div class="tour-stage open" id="tour-stage"><img id="tour-image" src="/assets/pixel-exterior.webp" alt="Exterior de Pixel"><div class="door left"></div><div class="door right"></div><div class="travel-label" aria-hidden="true">PIXEL<br><small>{t('UN PASO MÁS CERCA DE CASA','ONE STEP CLOSER TO HOME')}</small></div><div class="tour-caption" aria-live="polite"><small id="scene-kicker">01 / LLEGAR</small><h2 id="scene-title">Tu primera mirada.</h2><p id="scene-description">Pixel, en La Magdalena.</p></div></div><aside class="tour-controls"><div class="eyebrow">{t('ELIGE POR DÓNDE SEGUIR','CHOOSE YOUR NEXT STEP')}</div><div class="journey-progress"><span id="journey-counter">01</span><small>/ 04</small></div><div class="floor-buttons">'''+''.join(f'<button data-scene="{i}" aria-pressed="{str(i==0).lower()}"><b>0{i+1}</b>{t(es,en)}</button>' for i,es,en in [(0,'Llegar','Arrive'),(1,'Entrar','Step inside'),(2,'Habitar','Come home'),(3,'Disfrutar','Unwind')])+f'''</div><div class="journey-actions"><button id="journey-prev" class="text-link">{t('Anterior','Previous')}</button><button id="journey-next" class="button">{t('Continuar','Continue')}</button></div><p class="tour-note">{t('Secuencia conceptual con renders 2D. Las paradas no representan pisos ni una ruta física verificada. Puedes saltar a cualquier espacio.','Conceptual sequence using 2D renders. Stops do not represent floors or a verified physical route. Jump to any space at any time.')}</p><button class="text-link" id="tour-to-details">{t('Ir directo a la información','Go straight to project details')}</button></aside></div><div class="tour-bottom"><span>{t('¿Prefieres recorrer un espacio real en 360?','Prefer to explore an existing 360 space?')}</span><a href="https://pixel.com.ec/tour360/deparNuevo/" target="_blank" rel="noopener">{t('Abrir tour 360 publicado por Pixel','Open Pixel’s existing 360 tour')}</a></div></dialog>'''
